// The run contract: what state a step can be in, which moves are legal, and which effects
// stop at a gate. No React and no DOM, so the rules run under `node --test` and can be
// shared by a server, a worker and every shell that renders a run.

export type RunState = 'queued' | 'running' | 'needs-approval' | 'done' | 'failed';

export const RUN_STATES: readonly RunState[] = ['queued', 'running', 'needs-approval', 'done', 'failed'];

// The words a person reads, and a screen reader hears, for each state. Colour and icon are
// never the only signal; RunStep always renders this label.
export const runStateLabel: Record<RunState, string> = {
  queued: 'Queued',
  running: 'Running',
  'needs-approval': 'Needs approval',
  done: 'Done',
  failed: 'Failed',
};

// Legal moves. A step waits, runs, may stop at a gate, and ends. `done` and `failed` are
// final: a retry is a new step, so the record of what happened is never rewritten.
// From a gate, approval resumes the step and a denial or a timeout fails it.
const NEXT: Record<RunState, readonly RunState[]> = {
  queued: ['running', 'failed'],
  running: ['needs-approval', 'done', 'failed'],
  'needs-approval': ['running', 'failed'],
  done: [],
  failed: [],
};

export function canTransition(from: RunState, to: RunState): boolean {
  return NEXT[from].includes(to);
}

export function isSettled(state: RunState): boolean {
  return state === 'done' || state === 'failed';
}

// What a tool call does to the world. Reading is free; everything else changes something
// a person owns and waits for them.
export type Effect = 'read' | 'write' | 'send' | 'spend';

export const EFFECTS: readonly Effect[] = ['read', 'write', 'send', 'spend'];

export function needsGate(effect: Effect): boolean {
  return effect !== 'read';
}

export type RunSummary = {
  total: number;
  done: number;
  failed: number;
  /** A step is waiting on a person. Nothing after it has started. */
  blocked: boolean;
  /** Every step has ended. */
  settled: boolean;
  /** One line for a header or a live region, e.g. "2 of 5 steps done. Waiting for approval." */
  label: string;
};

export function summarizeRun(states: readonly RunState[]): RunSummary {
  const total = states.length;
  const done = states.filter((s) => s === 'done').length;
  const failed = states.filter((s) => s === 'failed').length;
  const blocked = states.includes('needs-approval');
  const settled = total > 0 && states.every(isSettled);
  const progress = `${done} of ${total} ${total === 1 ? 'step' : 'steps'} done.`;
  let tail = '';
  if (total === 0) tail = '';
  else if (blocked) tail = ' Waiting for approval.';
  else if (failed > 0) tail = ` ${failed} failed.`;
  else if (states.includes('running')) tail = ' Running.';
  return { total, done, failed, blocked, settled, label: total === 0 ? 'No steps yet.' : progress + tail };
}

import * as React from "react"
import { cn } from "cn"
import { Check, Circle, LoaderCircle, ShieldAlert, X } from "lucide-react"
import { type RunState, runStateLabel } from "./run-state.ts"

// One step of an agent run: who did what, in which state, and how long it took. Every
// action an agent takes is a step, in order, so there is no hidden work. The surface is
// ink: a run reads as a log on the night shell, never on glass (glass carries controls,
// not records).
//
// State is carried three ways at once: an icon, a tone, and the words from run-state.ts.
// The words are always in the DOM, so nothing depends on colour.

const stateIcon = {
  queued: Circle,
  running: LoaderCircle,
  "needs-approval": ShieldAlert,
  done: Check,
  failed: X,
} satisfies Record<RunState, React.ComponentType<React.ComponentProps<"svg">>>

const stateTone: Record<RunState, string> = {
  queued: "text-on-surface/50",
  running: "text-signal",
  "needs-approval": "text-accent-bright",
  done: "text-on-surface",
  failed: "text-error",
}

function RunTimeline({ className, label = "Run", ...props }: React.ComponentProps<"ol"> & { label?: string }) {
  return (
    <ol
      data-slot="run-timeline"
      aria-label={label}
      className={cn("flex list-none flex-col gap-2", className)}
      {...props}
    />
  )
}

type RunStepProps = Omit<React.ComponentProps<"li">, "title"> & {
  state: RunState
  /** What is being done, as a verb phrase: "Read the repository". */
  title: React.ReactNode
  /** Who is doing it and with what: "Research · 14 files". */
  detail?: React.ReactNode
  /** Duration or a short status of record. Falls back to the state label. */
  meta?: React.ReactNode
}

function RunStep({ state, title, detail, meta, className, ...props }: RunStepProps) {
  const Icon = stateIcon[state]
  return (
    <li
      data-slot="run-step"
      data-state={state}
      aria-current={state === "running" ? "step" : undefined}
      className={cn(
        "flex items-center gap-3 rounded-md border border-hairline bg-glass-opaque px-3 py-3 text-on-surface",
        state === "needs-approval" && "border-accent-bright/60",
        className
      )}
      {...props}
    >
      <Icon aria-hidden="true" className={cn("size-4 shrink-0", stateTone[state])} />
      <div className="min-w-0 flex-1">
        <p className="text-label-md font-medium text-pretty">{title}</p>
        {detail ? <p className="mt-0.5 text-label-sm opacity-70">{detail}</p> : null}
      </div>
      {/* Not through cn(): it reads a custom size (text-code) and a colour (text-signal) as one
          conflicting group and drops the size. */}
      <p className={`shrink-0 font-mono text-code ${stateTone[state]}`}>
        {meta ? <span className="sr-only">{runStateLabel[state]}. </span> : null}
        {meta ?? runStateLabel[state]}
      </p>
    </li>
  )
}

export { RunStep, RunTimeline }
export type { RunStepProps }

import * as React from "react"
import { cn } from "cn"
import { ShieldCheck, Terminal } from "lucide-react"

// A tool invocation shown as it was made: the tool's name, its exact arguments, and the
// scope it ran under. Nothing is summarised away; a person can copy the arguments and
// check them.
type ToolCallProps = React.ComponentProps<"section"> & {
  /** The tool as the agent called it: "github.read_files". */
  name: string
  /** The scope the call ran under: "read-only". */
  scope?: React.ReactNode
  /** The arguments, verbatim. Rendered in a scrollable pre; never truncated. */
  args?: string
  /** How long the grant lasts or what it covers: "Scope granted for this run only." */
  note?: React.ReactNode
}

function ToolCall({ name, scope, args, note, className, ...props }: ToolCallProps) {
  return (
    <section
      data-slot="tool-call"
      aria-label={`Tool call: ${name}`}
      className={cn("flex flex-col gap-3 rounded-lg border border-hairline bg-primary p-4 text-on-surface", className)}
      {...props}
    >
      <header className="flex items-center gap-2">
        <Terminal aria-hidden="true" className="size-4 shrink-0 opacity-70" />
        <code className="min-w-0 flex-1 truncate font-mono text-code">{name}</code>
        {scope ? <span className="shrink-0 text-label-sm opacity-70">{scope}</span> : null}
      </header>
      {args ? (
        <pre className="overflow-x-auto rounded-md bg-glass-opaque p-3 font-mono text-code opacity-80">
          <code>{args}</code>
        </pre>
      ) : null}
      {note ? <p className="text-label-sm opacity-70">{note}</p> : null}
    </section>
  )
}

// The gate a run stops at before any write, send or spend (run-state.ts, needsGate). It
// states the actor, the action and the scope, then waits. The actions are children so the
// consumer owns the handlers; pass Buttons, the first one being the approval. Approval
// applies to this action only, and the note says what has not happened yet.
type ApprovalGateProps = Omit<React.ComponentProps<"section">, "title"> & {
  title?: React.ReactNode
  /** Actor, action and object in one sentence: "Build wants to open a pull request with 3 changed files." */
  request: React.ReactNode
  /** The exact scope being asked for: "repo.write · example-org/logger". */
  scope?: React.ReactNode
  /** What is true until a choice is made: "Nothing is written until you choose." */
  note?: React.ReactNode
}

function ApprovalGate({ title = "Approval needed", request, scope, note, children, className, ...props }: ApprovalGateProps) {
  const id = React.useId()
  return (
    <section
      data-slot="approval-gate"
      role="group"
      aria-labelledby={`${id}-title`}
      aria-describedby={`${id}-request`}
      className={cn("flex flex-col gap-3 rounded-lg border border-accent-bright/60 bg-primary p-4 text-on-surface", className)}
      {...props}
    >
      <header className="flex items-center gap-2">
        <ShieldCheck aria-hidden="true" className="size-4 shrink-0 text-accent-bright" />
        <h3 id={`${id}-title`} className="text-label-md font-medium">
          {title}
        </h3>
      </header>
      <p id={`${id}-request`} className="text-body-md text-pretty">
        {request}
      </p>
      {scope ? <p className="font-mono text-code opacity-70">{scope}</p> : null}
      <div data-slot="approval-actions" className="flex flex-wrap gap-2">
        {children}
      </div>
      {note ? <p className="text-label-sm opacity-70">{note}</p> : null}
    </section>
  )
}

export { ApprovalGate, ToolCall }
export type { ApprovalGateProps, ToolCallProps }

import * as React from "react"
import { cn } from "cn"
import { Brain } from "lucide-react"
import { stateContract } from "../primitives/material.ts"

// An answer with its evidence attached. Three parts: the meta row (which route answered,
// what memory shaped it), the body with numbered citation marks, and the sources those
// marks point at. A mark and its source share an index and an anchor, so a claim is one
// keypress from its proof. A sentence with no mark is the model's own reasoning and reads
// as such.

function Answer({ className, ...props }: React.ComponentProps<"article">) {
  return (
    <article
      data-slot="answer"
      className={cn("flex flex-col gap-4 rounded-lg border border-hairline bg-glass-opaque p-6 text-on-surface", className)}
      {...props}
    />
  )
}

function AnswerMeta({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="answer-meta" className={cn("flex flex-wrap items-center gap-2", className)} {...props} />
}

function AnswerBody({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="answer-body" className={cn("max-w-[68ch] text-body-md text-pretty", className)} {...props} />
}

// The numbered mark inside the body. `sourcesId` is the id given to AnswerSources, so
// marks from two answers on one page never collide.
function CitationMark({ index, sourcesId, className, ...props }: Omit<React.ComponentProps<"a">, "href"> & { index: number; sourcesId: string }) {
  return (
    // The size sits on the sup and the colour on the link: cn() treats a custom size and a
    // colour on one element as the same group and keeps only the last.
    <sup className="font-mono text-code">
      <a
        data-slot="citation-mark"
        href={`#${sourcesId}-${index}`}
        aria-label={`Source ${index}`}
        className={cn(
          "rounded-xs px-0.5 text-accent-bright focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-focus",
          className
        )}
        {...props}
      >
        [{index}]
      </a>
    </sup>
  )
}

function AnswerSources({ id, label = "Sources", className, ...props }: React.ComponentProps<"ol"> & { id: string; label?: string }) {
  return (
    <ol
      id={id}
      data-slot="answer-sources"
      aria-label={label}
      className={cn("flex list-none flex-wrap gap-2", className)}
      {...props}
    />
  )
}

type SourceChipProps = Omit<React.ComponentProps<"a">, "title"> & {
  index: number
  /** The id of the AnswerSources list this chip sits in. */
  sourcesId: string
  title: React.ReactNode
  /** Where it lives, for trust at a glance: "github.com". */
  domain?: React.ReactNode
}

// A source is always a link. It takes the state contract (press, focus ring, gated hover)
// because it is interactive; the list item around it carries the anchor a mark jumps to.
function SourceChip({ index, sourcesId, title, domain, className, ...props }: SourceChipProps) {
  return (
    <li id={`${sourcesId}-${index}`} className="scroll-mt-24">
      <a
        data-slot="source-chip"
        className={cn(
          "inline-flex min-h-11 items-center gap-2 rounded-md border border-hairline bg-primary px-3 py-2 text-on-surface fine-hover:border-highlight active:bg-glass-opaque",
          stateContract,
          className
        )}
        {...props}
      >
        <span aria-hidden="true" className="font-mono text-code text-accent-bright">
          {index}
        </span>
        <span className="text-label-md font-medium">{title}</span>
        {domain ? <span className="text-label-sm opacity-70">{domain}</span> : null}
      </a>
    </li>
  )
}

// Which model handled the work. A route, not an identity: people choose outcomes, the
// router chooses models, and the surface always says which one answered. `mark` takes a
// partner's official mark only; with none, an empty dashed slot holds the place rather
// than a redrawn logo.
type ModelRouteProps = React.ComponentProps<"span"> & {
  route: React.ReactNode
  detail?: React.ReactNode
  mark?: React.ReactNode
}

function ModelRoute({ route, detail, mark, className, ...props }: ModelRouteProps) {
  return (
    <span
      data-slot="model-route"
      className={cn("inline-flex items-center gap-2 rounded-full border border-hairline bg-primary px-3 py-1.5 text-on-surface", className)}
      {...props}
    >
      {mark ?? <span aria-hidden="true" data-slot="partner-mark-slot" className="size-4 shrink-0 rounded-full border border-dashed border-on-surface/40" />}
      <span className="text-label-md font-medium">{route}</span>
      {detail ? <span className="text-label-sm opacity-70">{detail}</span> : null}
    </span>
  )
}

// Says that stored memory shaped this answer. Static by default; wrap it in a link or a
// button to open the notes, where each can be edited or removed.
function MemoryChip({ className, children, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="memory-chip"
      className={cn("inline-flex items-center gap-2 rounded-full border border-hairline bg-primary px-3 py-1.5 text-on-surface", className)}
      {...props}
    >
      <Brain aria-hidden="true" className="size-4 shrink-0 opacity-70" />
      <span className="text-label-sm">{children}</span>
    </span>
  )
}

export { Answer, AnswerBody, AnswerMeta, AnswerSources, CitationMark, MemoryChip, ModelRoute, SourceChip }
export type { ModelRouteProps, SourceChipProps }

import * as React from "react"
import { cn } from "cn"
import { Send } from "lucide-react"
import { Button } from "../primitives/ui/button.tsx"

// The prompt composer. Before anything is sent, a person can see which route will handle
// it and what the agents are allowed to touch: `route` takes a ModelRoute, `tools` takes
// the scope summary, and tools start at none. It is a plain form, so it submits with no
// script and works as a Server Action target; the consumer owns `action` or `onSubmit`.
//
// Focus: the ring belongs to the whole composer, not the textarea inside it, so the
// outline is drawn on the form while the textarea has focus. The textarea's own outline is
// handed to the form, not removed.
type ComposerProps = React.ComponentProps<"form"> & {
  /** Accessible name for the text field. */
  label?: string
  placeholder?: string
  /** Field name in the submitted form data. */
  name?: string
  rows?: number
  route?: React.ReactNode
  tools?: React.ReactNode
  /** Accessible name for the send button. */
  sendLabel?: string
  disabled?: boolean
}

function Composer({
  label = "Message",
  placeholder = "Ask, or give the team a mission.",
  name = "prompt",
  rows = 2,
  route,
  tools,
  sendLabel = "Send",
  disabled = false,
  className,
  ...props
}: ComposerProps) {
  const id = React.useId()
  return (
    <form
      data-slot="composer"
      className={cn(
        "flex flex-col gap-3 rounded-xl border border-hairline bg-glass-opaque p-4 text-on-surface",
        "has-[textarea:focus-visible]:outline-2 has-[textarea:focus-visible]:outline-offset-[3px] has-[textarea:focus-visible]:outline-focus",
        className
      )}
      {...props}
    >
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <textarea
        id={id}
        name={name}
        rows={rows}
        placeholder={placeholder}
        disabled={disabled}
        className="w-full resize-none bg-transparent text-body-md placeholder:text-on-surface/60 focus-visible:outline-0 disabled:opacity-50"
      />
      <div className="flex items-center justify-between gap-2">
        <div data-slot="composer-context" className="flex min-w-0 flex-wrap items-center gap-2">
          {route}
          {tools}
        </div>
        <Button type="submit" material="paper" size="icon" aria-label={sendLabel} disabled={disabled}>
          <Send aria-hidden="true" />
        </Button>
      </div>
    </form>
  )
}

export { Composer }
export type { ComposerProps }

export { EFFECTS, RUN_STATES, canTransition, isSettled, needsGate, runStateLabel, summarizeRun } from './run-state.ts';
export type { Effect, RunState, RunSummary } from './run-state.ts';
export { RunStep, RunTimeline } from './run-step.tsx';
export type { RunStepProps } from './run-step.tsx';
export { ApprovalGate, ToolCall } from './tool-call.tsx';
export type { ApprovalGateProps, ToolCallProps } from './tool-call.tsx';
export {
  Answer,
  AnswerBody,
  AnswerMeta,
  AnswerSources,
  CitationMark,
  MemoryChip,
  ModelRoute,
  SourceChip,
} from './answer.tsx';
export type { ModelRouteProps, SourceChipProps } from './answer.tsx';
export { Composer } from './composer.tsx';
export type { ComposerProps } from './composer.tsx';
